create table xxcus.xxcmp_conclusion_templates (
    risk_tier             varchar2(30 byte) not null enable,
    template_name         varchar2(240 byte) not null enable,
    template_text         clob not null enable,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_conclusion_templates
    add constraint xxcmp_conclusion_templates_ck1
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_conclusion_templates
    add constraint xxcmp_conclusion_templates_pk primary key ( risk_tier )
        using index enable;


